// ── Validate filename format ────────────────────────────────────
// BookLeaf convention: ISBN_bookname.ext
// ISBN must be 10 or 13 digits

const filename = $json.name || '';
const fileId = $json.id || '';
const mimeType = $json.mimeType || '';

// Extract basename without extension
const basename = filename.replace(/\.[^.]+$/, '');
const parts = basename.split('_');

if (parts.length < 2) {
  throw new Error(`Invalid filename format: '${filename}'. Expected: ISBN_bookname.ext`);
}

const isbn = parts[0];

if (!/^\d{10}$|^\d{13}$/.test(isbn)) {
  throw new Error(`Invalid ISBN '${isbn}' in filename '${filename}'. Must be 10 or 13 digits.`);
}

// Validate file extension
const ext = filename.split('.').pop()?.toLowerCase();
if (!['pdf', 'png', 'jpg', 'jpeg'].includes(ext)) {
  throw new Error(`Unsupported format '.${ext}'. Supported: PDF, PNG`);
}

console.log(`Validated: ISBN=${isbn} | File=${filename} | MimeType=${mimeType}`);

return [{
  json: {
    isbn,
    filename,
    fileId,
    mimeType,
    ext,
    uploadedAt: new Date().toISOString()
  }
}];

// Build the annotated image filename and prepare upload metadata
const isbn = $('Validate Filename & Extract ISBN').item.json.isbn;
const annotatedPath = $json.annotated_image_path;

return [{
  json: {
    isbn,
    annotatedFilename: `${isbn}_annotated.png`,
    annotatedPath,
    violations: $json.violations,
    confidence: $json.confidence,
    primaryIssue: $json.primary_issue,
    correctionText: $json.correction_text,
    ocrEngine: $json.ocr_engine,
    timestamp: $json.timestamp,
    processingTimeMs: $json.processing_time_ms
  }
}];
